import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

export default function Dashboard() {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showAchievement, setShowAchievement] = useState(false);

  useEffect(() => {
    loadUserData();
    loadSessions();
  }, []);

  useEffect(() => {
    // Show achievement for 5+ sessions
    if (sessions.length >= 5 && !localStorage.getItem('achievement_5sessions')) {
      setShowAchievement(true);
      localStorage.setItem('achievement_5sessions', 'true');
      setTimeout(() => setShowAchievement(false), 5000);
    }
  }, [sessions.length]);

  const loadUserData = () => {
    const userData = localStorage.getItem('currentUser');
    if (userData) {
      setUser(JSON.parse(userData));
    }
  };

  const loadSessions = async () => {
    try {
      const token = localStorage.getItem('authToken');
      if (!token) {
        console.log('No token found');
        setLoading(false);
        return;
      }

      const response = await fetch('http://localhost:8000/api/sessions', {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      if (response.ok) {
        const data = await response.json();
        console.log('✅ Sessions loaded:', data);
        setSessions(data);
      } else {
        console.error('❌ Failed to load sessions:', response.status);
      }
    } catch (error) {
      console.error('❌ Error loading sessions:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.clear();
    navigate('/auth', { replace: true });
  };

  const handleStartSession = (tutorId, subject) => {
    const roomId = `room_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    console.log('🚀 Starting NEW session with tutorId:', tutorId, 'subject:', subject);

    navigate(`/video/${roomId}`, { 
      state: { 
        tutorId: tutorId, 
        subject: subject, 
        resuming: false 
      },
      replace: true
    });
  };

  const handleResumeSession = (session) => {
    navigate(`/video/${session.session_id}`, { 
      state: { 
        tutorId: session.tutor_id,
        subject: session.subject, 
        resuming: true 
      },
      replace: true
    });
  };

  const tutors = [
    { 
      id: 'omkar_ai',
      name: 'Omkar', 
      subject: 'AI & ML', 
      description: 'Expert in Artificial Intelligence and Machine Learning', 
      icon: '🧑‍💻',
      gradient: 'from-blue-600 to-cyan-600',
      bgGradient: 'from-blue-500/10 to-cyan-500/10'
    },
    { 
      id: 'priya_biology',
      name: 'Priya', 
      subject: 'Biology', 
      description: 'Passionate Biology tutor specializing in life sciences', 
      icon: '👩‍🔬',
      gradient: 'from-purple-600 to-pink-600',
      bgGradient: 'from-purple-500/10 to-pink-500/10'
    }
  ];

  const totalMessages = sessions.reduce((sum, session) => sum + session.message_count, 0);
  const streak = Math.min(sessions.length, 7); // Simple streak calculation

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-950 via-purple-950 to-slate-950">

      {/* Achievement Popup */}
      {showAchievement && (
        <div className="fixed top-8 right-8 z-50 bg-gradient-to-r from-yellow-500/90 to-orange-500/90 backdrop-blur-xl rounded-2xl p-6 border border-yellow-300/30 shadow-2xl animate-bounce">
          <div className="flex items-center gap-4">
            <div className="text-5xl">🏆</div>
            <div>
              <div className="text-white font-bold text-lg">Achievement Unlocked!</div>
              <div className="text-yellow-100 text-sm">5 Learning Sessions Completed</div>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <div className="border-b border-white/10 bg-black/20 backdrop-blur-xl">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <div className="w-14 h-14 bg-gradient-to-br from-blue-500 to-purple-600 rounded-2xl flex items-center justify-center text-white font-bold text-xl shadow-lg">
                {user?.name?.charAt(0)?.toUpperCase() || 'S'}
              </div>
              <div>
                <h2 className="text-xl font-bold text-white">
                  Welcome back, {user?.name || 'Student'}! 👋
                </h2>
                <p className="text-sm text-gray-400">{user?.email}</p>
              </div>
            </div>
            <button 
              onClick={handleLogout}
              className="px-6 py-3 bg-red-500/10 hover:bg-red-500/20 border border-red-500/30 text-red-400 rounded-xl transition-all duration-300 font-medium"
            >
              Logout
            </button>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">

        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-12">

          {/* Total Sessions */}
          <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6 hover:scale-105 transition-transform duration-300">
            <div className="flex items-center justify-between mb-4">
              <div className="w-14 h-14 bg-blue-500/20 rounded-xl flex items-center justify-center text-3xl">
                📚
              </div>
              <div className="text-right">
                <div className="text-4xl font-black text-white">{sessions.length}</div>
                <div className="text-gray-400 text-sm font-medium">Sessions</div>
              </div>
            </div>
            <div className="h-2 bg-blue-500/20 rounded-full overflow-hidden">
              <div className="h-full bg-gradient-to-r from-blue-500 to-cyan-500" style={{ width: `${Math.min((sessions.length / 10) * 100, 100)}%` }}></div>
            </div>
          </div>

          {/* Messages */}
          <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6 hover:scale-105 transition-transform duration-300">
            <div className="flex items-center justify-between mb-4">
              <div className="w-14 h-14 bg-purple-500/20 rounded-xl flex items-center justify-center text-3xl">
                💬
              </div>
              <div className="text-right">
                <div className="text-4xl font-black text-white">{totalMessages}</div>
                <div className="text-gray-400 text-sm font-medium">Messages</div>
              </div>
            </div>
            <div className="h-2 bg-purple-500/20 rounded-full overflow-hidden">
              <div className="h-full bg-gradient-to-r from-purple-500 to-pink-500" style={{ width: `${Math.min((totalMessages / 50) * 100, 100)}%` }}></div>
            </div>
          </div>

          {/* Streak */}
          <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6 hover:scale-105 transition-transform duration-300">
            <div className="flex items-center justify-between mb-4">
              <div className="w-14 h-14 bg-orange-500/20 rounded-xl flex items-center justify-center text-3xl">
                🔥
              </div>
              <div className="text-right">
                <div className="text-4xl font-black text-white">{streak}</div>
                <div className="text-gray-400 text-sm font-medium">Day Streak</div>
              </div>
            </div>
            <div className="h-2 bg-orange-500/20 rounded-full overflow-hidden">
              <div className="h-full bg-gradient-to-r from-orange-500 to-red-500" style={{ width: `${(streak / 7) * 100}%` }}></div>
            </div>
          </div>

          {/* Active Tutors */}
          <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6 hover:scale-105 transition-transform duration-300">
            <div className="flex items-center justify-between mb-4">
              <div className="w-14 h-14 bg-green-500/20 rounded-xl flex items-center justify-center text-3xl">
                🎯
              </div>
              <div className="text-right">
                <div className="text-4xl font-black text-white">{tutors.length}</div>
                <div className="text-gray-400 text-sm font-medium">AI Tutors</div>
              </div>
            </div>
            <div className="h-2 bg-green-500/20 rounded-full overflow-hidden">
              <div className="h-full bg-gradient-to-r from-green-500 to-emerald-500" style={{ width: '100%' }}></div>
            </div>
          </div>
        </div>

        {/* AI Tutors Section */}
        <div className="mb-12">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-3xl font-black text-white">Choose Your AI Tutor</h3>
            <div className="flex items-center gap-2 px-4 py-2 bg-blue-500/10 border border-blue-500/30 rounded-full text-blue-400 text-sm font-medium">
              <span className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></span>
              All tutors online
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {tutors.map((tutor) => (
              <div 
                key={tutor.id}
                className={`group relative bg-gradient-to-br ${tutor.bgGradient} backdrop-blur-xl border border-white/10 rounded-3xl p-8 hover:border-white/30 transition-all duration-300 hover:scale-[1.02] overflow-hidden`}
              >
                {/* Glow effect */}
                <div className={`absolute inset-0 bg-gradient-to-br ${tutor.gradient} opacity-0 group-hover:opacity-10 transition-opacity duration-300`}></div>

                <div className="relative flex items-start gap-6">
                  <div className="flex-shrink-0 text-7xl">{tutor.icon}</div>
                  <div className="flex-1">
                    <h4 className="text-2xl font-bold text-white mb-2">{tutor.name}</h4>
                    <p className={`text-lg font-semibold bg-gradient-to-r ${tutor.gradient} bg-clip-text text-transparent mb-3`}>
                      {tutor.subject}
                    </p>
                    <p className="text-gray-300 text-sm mb-6 leading-relaxed">{tutor.description}</p>
                    <button
                      onClick={() => handleStartSession(tutor.id, tutor.subject)}
                      className={`w-full px-6 py-4 bg-gradient-to-r ${tutor.gradient} hover:shadow-2xl text-white rounded-xl font-bold transition-all duration-300 transform group-hover:scale-105 flex items-center justify-center gap-2`}
                    >
                      Start Session
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" />
                      </svg>
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Recent Sessions */}
        <div>
          <h3 className="text-3xl font-black text-white mb-6">Recent Sessions</h3>

          {loading ? (
            <div className="flex flex-col items-center justify-center py-20">
              <div className="relative w-16 h-16">
                <div className="absolute inset-0 border-4 border-blue-500/30 rounded-full"></div>
                <div className="absolute inset-0 border-4 border-t-blue-500 rounded-full animate-spin"></div>
              </div>
              <p className="text-gray-400 mt-6 font-medium">Loading your sessions...</p>
            </div>
          ) : sessions.length === 0 ? (
            <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-3xl p-16 text-center">
              <div className="w-24 h-24 bg-blue-500/10 rounded-full flex items-center justify-center mx-auto mb-6">
                <span className="text-6xl">📚</span>
              </div>
              <h4 className="text-2xl font-bold text-white mb-3">No sessions yet</h4>
              <p className="text-gray-400 mb-8">Start your first learning session with an AI tutor above!</p>
              <div className="inline-flex items-center gap-2 px-6 py-3 bg-blue-500/10 border border-blue-500/30 rounded-full text-blue-400 text-sm font-medium">
                <span>👆</span>
                <span>Click "Start Session" above to begin</span>
              </div>
            </div>
          ) : (
            <div className="grid grid-cols-1 gap-4">
              {sessions.map((session) => (
                <div 
                  key={session.session_id}
                  className="group bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6 hover:border-purple-500/50 hover:bg-white/10 transition-all duration-300"
                >
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-6">
                      <div className="text-5xl">
                        {session.tutor_id === 'omkar_ai' ? '🧑‍💻' : '👩‍🔬'}
                      </div>
                      <div>
                        <h4 className="text-xl font-bold text-white mb-1">
                          Session with {session.tutor_id === 'omkar_ai' ? 'Omkar' : 'Priya'}
                        </h4>
                        <div className="flex items-center gap-4 text-sm text-gray-400">
                          <span>📅 {new Date(session.created_at).toLocaleDateString()}</span>
                          <span>💬 {session.message_count} messages</span>
                        </div>
                      </div>
                    </div>
                    <button
                      onClick={() => handleResumeSession(session)}
                      className="px-8 py-3 bg-gradient-to-r from-purple-600 to-pink-600 hover:shadow-lg hover:shadow-purple-500/50 text-white rounded-xl font-bold transition-all duration-300 transform hover:scale-105"
                    >
                      Resume
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
